<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use App\Core\Database;use App\Services\DivisionProgressionService;
$pdo=Database::connection();
$dance=(string)($_GET['dance']??'bachata');if(!in_array($dance,['bachata','salsa','dance_cup'],true))$dance='bachata';
$division=(string)($_GET['division']??'novice');$role=(string)($_GET['role']??'leader');$showOut=!empty($_GET['show_out']);
$allowedDivisions=['all','novice','intermediate','advanced'];$allowedRoles=['leader','follower'];if(!in_array($division,$allowedDivisions,true))$division='novice';if(!in_array($role,$allowedRoles,true))$role='leader';
function leaderboardLabel(string $value):string{if($value==='all')return 'All Divisions';return DivisionProgressionService::label($value);}function danceLabel(string $dance):string{return match($dance){'salsa'=>'Salsa','dance_cup'=>'BDC Dance Cup',default=>'Bachata'};}
$rows=[];$cupRows=[];
if($dance==='dance_cup'){
 $cupRows=$pdo->query("SELECT d.id,d.entrant_name,d.category_name,d.placement,d.updated_at,e.name event_name,e.event_date,c.id competitor_id,c.bdc_id,c.country,c.photo_url FROM bdc_dance_cup_results d JOIN bdc_events e ON e.id=d.event_id LEFT JOIN bdc_competitors c ON c.id=d.competitor_id ORDER BY CASE WHEN d.placement IS NULL THEN 999999 ELSE d.placement END ASC,e.event_date DESC,d.id DESC")->fetchAll();
}else{
 $roleJoin=$division==='all'?"AND pt.dance_role IN ('leader','follower')":'AND pt.dance_role=:role';$selectedEventsCondition=$division==='all'?'1=1':'pt.division=:selected_division_events';$selectedFirstCondition=$division==='all'?'1=1':'pt.division=:selected_division_first';$selectedSecondCondition=$division==='all'?'1=1':'pt.division=:selected_division_second';$selectedThirdCondition=$division==='all'?'1=1':'pt.division=:selected_division_third';$selectedDateCondition=$division==='all'?'1=1':'pt.division=:selected_division_date';
 $stmt=$pdo->prepare("SELECT MIN(c.id) competitor_id,GROUP_CONCAT(DISTINCT c.bdc_id ORDER BY c.bdc_id SEPARATOR ' / ') bdc_id,COALESCE(g.display_name,MAX(c.exact_name)) competitor_name,MAX(c.country) country,MAX(c.photo_url) photo_url,MAX(c.current_division) committed_division,MAX(c.novice_manual_out) novice_manual_out,MAX(c.intermediate_manual_out) intermediate_manual_out,MAX(c.division_override_reason) division_override_reason,ROUND(SUM(CASE WHEN pt.division='novice' THEN pt.points ELSE 0 END),2) novice_points,ROUND(SUM(CASE WHEN pt.division='intermediate' THEN pt.points ELSE 0 END),2) intermediate_points,ROUND(SUM(CASE WHEN pt.division='advanced' THEN pt.points ELSE 0 END),2) advanced_points,ROUND(SUM(CASE WHEN pt.dance_role='leader' THEN pt.points ELSE 0 END),2) leader_points,ROUND(SUM(CASE WHEN pt.dance_role='follower' THEN pt.points ELSE 0 END),2) follower_points,MAX(CASE WHEN pt.division='intermediate' THEN 1 ELSE 0 END) competed_intermediate,MAX(CASE WHEN pt.division='advanced' THEN 1 ELSE 0 END) competed_advanced,COUNT(DISTINCT CASE WHEN $selectedEventsCondition THEN pt.event_id END) selected_events,COUNT(DISTINCT CASE WHEN $selectedFirstCondition AND LOWER(TRIM(pt.placement)) IN('1','1st','first') THEN pt.event_id END) first_place_count,COUNT(DISTINCT CASE WHEN $selectedSecondCondition AND LOWER(TRIM(pt.placement)) IN('2','2nd','second') THEN pt.event_id END) second_place_count,COUNT(DISTINCT CASE WHEN $selectedThirdCondition AND LOWER(TRIM(pt.placement)) IN('3','3rd','third') THEN pt.event_id END) third_place_count,MAX(CASE WHEN $selectedDateCondition THEN COALESCE(e.event_date,DATE(pt.created_at)) END) last_result_date FROM bdc_competitors c LEFT JOIN bdc_point_transactions pt ON pt.competitor_id=c.id AND pt.dance_style=:dance_style $roleJoin AND NOT EXISTS (SELECT 1 FROM bdc_point_transactions duplicate_pt JOIN bdc_competitors duplicate_c ON duplicate_c.id=duplicate_pt.competitor_id WHERE COALESCE(duplicate_c.career_group_id,-duplicate_c.id)=COALESCE(c.career_group_id,-c.id) AND duplicate_pt.dance_style=pt.dance_style AND duplicate_pt.event_id <=> pt.event_id AND duplicate_pt.division=pt.division AND duplicate_pt.dance_role=pt.dance_role AND COALESCE(LOWER(TRIM(duplicate_pt.placement)),'')=COALESCE(LOWER(TRIM(pt.placement)),'') AND duplicate_pt.points=pt.points AND duplicate_pt.id<pt.id) LEFT JOIN bdc_events e ON e.id=pt.event_id LEFT JOIN bdc_competitor_career_groups g ON g.id=c.career_group_id WHERE c.status='active' AND c.show_on_leaderboard=1 GROUP BY COALESCE(c.career_group_id,-c.id),g.display_name");
 $params=['dance_style'=>$dance];if($division!=='all'){$params+=['selected_division_events'=>$division,'selected_division_first'=>$division,'selected_division_second'=>$division,'selected_division_third'=>$division,'selected_division_date'=>$division,'role'=>$role];}$stmt->execute($params);
 foreach($stmt->fetchAll() as $row){$novice=(float)$row['novice_points'];$intermediate=(float)$row['intermediate_points'];$advanced=(float)$row['advanced_points'];$points=$division==='all'?(float)$row['leader_points']+(float)$row['follower_points']:DivisionProgressionService::selectedPoints($division,$novice,$intermediate,$advanced);if($points<=0.0)continue;$eligibility=$division==='all'?['eligible'=>true,'reason'=>'','promoted_to'=>null]:DivisionProgressionService::eligibilityFor($division,$novice,$intermediate,$advanced,$row['committed_division'],(bool)$row['competed_intermediate'],(bool)$row['competed_advanced']);$manualOut=($division==='novice'&&(bool)$row['novice_manual_out'])||($division==='intermediate'&&(bool)$row['intermediate_manual_out']);$eligible=$eligibility['eligible']&&!$manualOut;if(!$eligible&&!$showOut)continue;$row['eligible']=$eligible;$promotedTo=$manualOut?match($division){'novice'=>'intermediate','intermediate'=>'advanced',default=>null}:$eligibility['promoted_to'];$row['status_label']=$promotedTo!==null?'Promoted to '.DivisionProgressionService::label($promotedTo):($eligibility['eligible']?'In Division':ucfirst($eligibility['reason']));$row['total_points']=$points;$rows[]=$row;}
 usort($rows,function(array $a,array $b):int{$points=(float)$b['total_points']<=>(float)$a['total_points'];if($points!==0)return $points;$date=strcmp((string)$b['last_result_date'],(string)$a['last_result_date']);if($date!==0)return $date;$events=(int)$b['selected_events']<=>(int)$a['selected_events'];if($events!==0)return $events;return strcmp((string)$a['bdc_id'],(string)$b['bdc_id']);});foreach($rows as $index=>&$row)$row['rank']=$index+1;unset($row);
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Leaderboard</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f6f8;color:#20242a}.hero{background:linear-gradient(135deg,#111827,#27272a);color:#fff}.board-card{border:0;border-radius:16px;box-shadow:0 8px 28px rgba(15,23,42,.08)}.rank-badge{display:inline-flex;align-items:center;justify-content:center;width:42px;height:42px;border-radius:50%;font-weight:800;background:#eceff3}.rank-1{background:#ffd76a}.rank-2{background:#dce2e8}.rank-3{background:#e5b27d}.avatar{width:48px;height:48px;border-radius:50%;object-fit:cover;background:#eceff3}.points{font-size:1.15rem;font-weight:800}.tabs{margin-top:-28px}.rule-note{font-size:.88rem}.out-row{background:#fff8e1}@media(max-width:575.98px){.discipline-tabs .btn{flex:1 1 100%}}</style></head><body><section class="hero py-5"><div class="container d-flex justify-content-between align-items-start gap-3 flex-wrap"><div><div class="text-uppercase small opacity-75">Bachata Dance Council</div><h1 class="display-6 fw-bold mb-2">Leaderboard</h1><p class="mb-0 opacity-75">Bachata and Salsa points are ranked independently. BDC Dance Cup displays placements only.</p></div><a class="btn btn-outline-light" href="<?=e(url('/'))?>">BDC Home</a></div></section><main class="container pb-5"><section class="card board-card tabs mb-4"><div class="card-body"><div class="d-flex gap-2 flex-wrap discipline-tabs"><?php foreach(['bachata'=>'Bachata','salsa'=>'Salsa','dance_cup'=>'BDC Dance Cup'] as $value=>$label):?><a class="btn <?=$dance===$value?'btn-dark':'btn-outline-dark'?>" href="?dance=<?=$value?>"><?=$label?></a><?php endforeach;?></div></div></section>
<?php if($dance==='dance_cup'):?><section class="card board-card"><div class="card-body p-0"><div class="p-4 border-bottom"><h2 class="h4 mb-1">BDC Dance Cup</h2><div class="text-muted">Placement history. No BDC points are allocated.</div></div><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Place</th><th>Entrant</th><th>BDC ID</th><th>Event</th><th>Category</th><th>Date</th></tr></thead><tbody><?php foreach($cupRows as $row):?><tr><td class="fw-bold"><?=e($row['placement']?ordinal((int)$row['placement']):'—')?></td><td><?=e($row['entrant_name'])?></td><td><?=e($row['bdc_id']?:'—')?></td><td><?=e($row['event_name'])?></td><td><?=e($row['category_name']?:'—')?></td><td><?=e($row['event_date']?:'—')?></td></tr><?php endforeach;?><?php if(!$cupRows):?><tr><td colspan="6" class="text-center py-5 text-muted">No BDC Dance Cup results yet.</td></tr><?php endif;?></tbody></table></div></div></section><?php else:?><section class="card board-card mb-4"><div class="card-body"><div class="mb-3"><strong><?=e(danceLabel($dance))?> Jack & Jill</strong></div><div class="d-flex gap-2 flex-wrap mb-3"><?php foreach(['all'=>'All Divisions','novice'=>'Novice','intermediate'=>'Intermediate','advanced'=>'Advanced'] as $value=>$label):?><a class="btn <?=$division===$value?'btn-dark':'btn-outline-dark'?>" href="?dance=<?=$dance?>&amp;division=<?=$value?>&amp;role=<?=$role?><?=$showOut?'&amp;show_out=1':''?>"><?=$label?></a><?php endforeach;?></div><?php if($division!=='all'):?><div class="d-flex gap-2 flex-wrap"><?php foreach(['leader'=>'Leader','follower'=>'Follower'] as $value=>$label):?><a class="btn <?=$role===$value?'btn-dark':'btn-outline-dark'?>" href="?dance=<?=$dance?>&amp;division=<?=$division?>&amp;role=<?=$value?><?=$showOut?'&amp;show_out=1':''?>"><?=$label?></a><?php endforeach;?></div><form method="get" class="mt-3"><input type="hidden" name="dance" value="<?=e($dance)?>"><input type="hidden" name="division" value="<?=e($division)?>"><input type="hidden" name="role" value="<?=e($role)?>"><label class="form-check form-switch"><input class="form-check-input" type="checkbox" name="show_out" value="1" <?=$showOut?'checked':''?> onchange="this.form.submit()"><span class="form-check-label">Show Out of Division competitors</span></label></form><?php endif;?></div></section><section class="card board-card"><div class="card-body p-0"><div class="d-flex justify-content-between p-4 border-bottom gap-3 flex-wrap"><div><h2 class="h4 mb-1"><?=e(danceLabel($dance))?> · <?=e(leaderboardLabel($division))?><?=$division==='all'?'':' · '.e(ucfirst($role))?></h2><div class="text-muted"><?=count($rows)?> ranked competitor<?=count($rows)===1?'':'s'?></div></div><span class="badge text-bg-success">Live</span></div><div class="px-4 py-3 border-bottom bg-light rule-note"><?php if($division==='all'):?>Totals combine Leader and Follower points within <?=e(danceLabel($dance))?> only.<?php elseif($division==='novice'):?>Novice dancers may move to Intermediate from 20 points and leave Novice after 25 points.<?php elseif($division==='intermediate'):?>Intermediate requires 20 Novice points. Dancers may move to Advanced from 25 Intermediate points and leave Intermediate after 30 points.<?php else:?>Advanced requires 25 Intermediate points and must be left after 40 Advanced points.<?php endif;?></div><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Rank</th><th>Competitor</th><th>Country</th><th class="text-end">Points</th><th>Events</th><th>🥇</th><th>🥈</th><th>🥉</th><th>Last Result</th></tr></thead><tbody><?php foreach($rows as $row):?><tr class="<?=empty($row['eligible'])?'out-row':''?>"><td><span class="rank-badge rank-<?=(int)$row['rank']<=3?(int)$row['rank']:0?>"><?=(int)$row['rank']?></span></td><td><div class="d-flex align-items-center gap-3"><img class="avatar" src="<?=e($row['photo_url']?:url('/public/assets/img/default-competitor.svg'))?>" alt=""><div><strong><?=e($row['competitor_name'])?></strong><?php if($row['bdc_id']):?><div class="small text-muted">BDC <?=e($row['bdc_id'])?></div><?php endif;?><?php if(empty($row['eligible'])):?><span class="badge text-bg-warning"><?=e($row['status_label'])?></span><?php endif;?></div></div></td><td><?=e($row['country']?:'—')?></td><td class="text-end points"><?=number_format((float)$row['total_points'],1)?></td><td><?=(int)$row['selected_events']?></td><td><?=(int)$row['first_place_count']?></td><td><?=(int)$row['second_place_count']?></td><td><?=(int)$row['third_place_count']?></td><td><?=e($row['last_result_date']?:'—')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9" class="text-center py-5 text-muted">No approved <?=e(danceLabel($dance))?> points are available for this selection.</td></tr><?php endif;?></tbody></table></div></div></section><?php endif;?></main></body></html>
<?php
function ordinal(int $n):string{$mod100=$n%100;if($mod100>=11&&$mod100<=13)return $n.'th';return $n.match($n%10){1=>'st',2=>'nd',3=>'rd',default=>'th'};}
